//! The material library (GDD §17, art bible §1.1): PBR surface materials for every `SurfaceKind`
//! and the current environment's named material list, built from tileable texture sets
//! (`assets/textures/<set>/{albedo,normal,rough}.ktx2`, generated by `tools/textures/`), plus
//! clear-coated car paints from `PaintInfo`.
//!
//! Surface materials are [`SurfaceMaterial`]s (StandardMaterial + a world-space extension for
//! macro variation, wetness/puddles and snow cover, see [`surface`]). Their UVs are **world
//! units**: a material repeats every `tile_u` u, matching rc_track's `MeshData` UVs.

mod coat_fix;
mod paint;
mod surface;

use std::collections::HashMap;
use std::path::Path;

use bevy::image::{ImageAddressMode, ImageLoaderSettings, ImageSampler, ImageSamplerDescriptor};
use bevy::math::Affine2;
use bevy::mesh::VertexAttributeValues;
use bevy::prelude::*;
use rc_core::prelude::*;
use serde::Deserialize;

pub use paint::{CarPaint, paint_material};
pub use surface::{SurfaceExtension, SurfaceMaterial};

pub(crate) fn build(app: &mut App) {
    coat_fix::build(app);
    surface::build(app);
    app.add_systems(Startup, load_textures);
}

/// Texture sets shipped in `assets/textures/<set>/` and the world size (u) one texture covers.
pub const TEXTURE_SETS: &[(&str, f32)] = &[
    ("asphalt", 3.0),
    ("cardboard", 2.0),
    ("carpet", 2.0),
    ("concrete", 4.0),
    ("dirt", 3.0),
    ("grass", 3.0),
    ("ice", 4.0),
    ("marble", 4.0),
    ("metal", 2.0),
    ("plaster", 4.0),
    ("plywood", 4.0),
    ("rubber", 2.0),
    ("stone", 4.0),
    ("tile", 2.667),
    ("toy_track", 2.0),
    ("vinyl", 2.667),
    ("wood_planks", 4.0),
];

/// Anisotropic filtering for ground textures seen at grazing angles.
const ANISOTROPY: u16 = 16;

/// A material of an environment's list (`assets/data/environments/<env>.ron`, `materials`).
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct MaterialDef {
    /// Texture set (see [`TEXTURE_SETS`]); `None` = a flat colour.
    pub set: Option<String>,
    /// Base colour, sRGB 0–1 (multiplies the albedo texture).
    pub color: [f32; 3],
    /// Perceptual roughness (multiplies the texture's roughness).
    pub roughness: f32,
    /// Metallic 0–1.
    pub metallic: f32,
    /// World size (u) one texture repeat covers; 0 = the set's natural size.
    pub tile_u: f32,
    /// Macro variation (breaks tiling): albedo modulation strength 0–1.
    pub variation: f32,
    /// Hue drift 0–1: macro patches turn drier — yellower and lighter (lawns, soil).
    pub hue_variation: f32,
    /// Clear coat 0–1 (varnish, glaze) and its roughness.
    pub clearcoat: f32,
    /// Roughness of the clear coat.
    pub clearcoat_roughness: f32,
    /// Receives wetness, puddles and snow from the weather (outdoor ground).
    pub weather: bool,
}

impl Default for MaterialDef {
    fn default() -> Self {
        Self {
            set: None,
            color: [1.0, 1.0, 1.0],
            roughness: 1.0,
            metallic: 0.0,
            tile_u: 0.0,
            variation: 0.15,
            hue_variation: 0.0,
            clearcoat: 0.0,
            clearcoat_roughness: 0.1,
            weather: true,
        }
    }
}

impl MaterialDef {
    fn textured(set: &str, color: [f32; 3], roughness: f32) -> Self {
        Self {
            set: Some(set.into()),
            color,
            roughness,
            ..default()
        }
    }

    /// Flat (untextured) material.
    fn flat(color: [f32; 3], roughness: f32) -> Self {
        Self {
            color,
            roughness,
            variation: 0.0,
            ..default()
        }
    }
}

/// Built-in material of each surface (environments override them by name).
pub fn default_surface(kind: SurfaceKind) -> MaterialDef {
    match kind {
        SurfaceKind::Asphalt => MaterialDef::textured("asphalt", [1.0; 3], 1.0),
        SurfaceKind::Stone => MaterialDef::textured("stone", [1.0; 3], 1.0),
        SurfaceKind::ToyTrack => MaterialDef {
            variation: 0.1,
            ..MaterialDef::textured("toy_track", [0.94, 0.48, 0.12], 1.0)
        },
        SurfaceKind::Wood => MaterialDef::textured("wood_planks", [1.0; 3], 1.0),
        SurfaceKind::Tile => MaterialDef::textured("tile", [1.0; 3], 1.0),
        SurfaceKind::Carpet => MaterialDef::textured("carpet", [0.71, 0.33, 0.24], 1.0),
        SurfaceKind::Cardboard => MaterialDef::textured("cardboard", [1.0; 3], 1.0),
        SurfaceKind::Grass => MaterialDef {
            variation: 0.3,
            hue_variation: 0.7,
            ..MaterialDef::textured("grass", [1.0; 3], 1.0)
        },
        SurfaceKind::Dirt => MaterialDef::textured("dirt", [1.0; 3], 1.0),
        SurfaceKind::Ice => MaterialDef {
            clearcoat: 0.6,
            clearcoat_roughness: 0.05,
            ..MaterialDef::textured("ice", [0.86, 0.93, 0.97], 1.0)
        },
        SurfaceKind::Oil => MaterialDef {
            clearcoat: 1.0,
            clearcoat_roughness: 0.04,
            ..MaterialDef::flat([0.045, 0.04, 0.035], 0.25)
        },
        // Shallow muddy water: the bottom shows through, the coat mirrors the sky.
        SurfaceKind::Water => MaterialDef {
            clearcoat: 1.0,
            clearcoat_roughness: 0.03,
            ..MaterialDef::flat([0.3, 0.3, 0.28], 0.2)
        },
    }
}

/// Toy-plastic palette (art bible §3.2).
const PALETTE: &[(&str, [f32; 3])] = &[
    ("plastic_red", [0.847, 0.224, 0.169]),
    ("plastic_blue", [0.184, 0.435, 0.839]),
    ("plastic_yellow", [0.949, 0.761, 0.188]),
    ("plastic_green", [0.243, 0.608, 0.310]),
    ("plastic_orange", [0.941, 0.478, 0.122]),
    ("plastic_white", [0.91, 0.90, 0.87]),
];

/// Names every environment provides (built-in defaults; environment files override them):
/// generic materials, the toy-plastic palette and the roles track visuals use.
pub fn builtin_materials() -> Vec<(String, MaterialDef)> {
    let generic = [
        ("wood", "wood_planks"),
        ("plywood", "plywood"),
        ("carpet", "carpet"),
        ("tile", "tile"),
        ("marble", "marble"),
        ("vinyl", "vinyl"),
        ("grass", "grass"),
        ("dirt", "dirt"),
        ("asphalt", "asphalt"),
        ("concrete", "concrete"),
        ("cardboard", "cardboard"),
        ("stone", "stone"),
        ("rubber", "rubber"),
        ("plaster", "plaster"),
        ("ice", "ice"),
    ];
    let mut out: Vec<(String, MaterialDef)> = generic
        .iter()
        .map(|(name, set)| (name.to_string(), MaterialDef::textured(set, [1.0; 3], 1.0)))
        .collect();
    let plastic = |color| MaterialDef {
        variation: 0.03,
        ..MaterialDef::flat(color, 0.24)
    };
    out.push(("plastic".into(), plastic([0.12, 0.125, 0.13])));
    out.extend(PALETTE.iter().map(|(n, c)| (n.to_string(), plastic(*c))));
    out.push((
        "metal".into(),
        MaterialDef {
            metallic: 1.0,
            ..MaterialDef::textured("metal", [0.75, 0.76, 0.78], 1.0)
        },
    ));
    let roles = [
        ("floor", MaterialDef::textured("concrete", [1.0; 3], 1.0)),
        (
            "wall",
            MaterialDef::textured("plaster", [0.93, 0.90, 0.85], 1.0),
        ),
        (
            "ceiling",
            MaterialDef::textured("plaster", [0.95, 0.95, 0.94], 1.0),
        ),
        ("trim", MaterialDef::textured("wood_planks", [1.0; 3], 1.0)),
        ("barrier", plastic([0.91, 0.90, 0.87])),
        ("ribbon_side", plastic([0.2, 0.2, 0.21])),
    ];
    out.extend(roles.into_iter().map(|(n, d)| (n.to_string(), d)));
    out
}

/// The three images of a texture set.
#[derive(Debug, Clone)]
struct TextureSet {
    albedo: Handle<Image>,
    normal: Handle<Image>,
    rough: Handle<Image>,
    tile_u: f32,
}

/// Surface materials of the current environment, car paints and the shared texture sets.
/// Inserted at startup; rc_render rebuilds the environment part when a session loads.
#[derive(Resource, Debug, Default)]
pub struct MaterialLibrary {
    environment: Option<String>,
    textures: HashMap<&'static str, TextureSet>,
    surfaces: HashMap<SurfaceKind, Handle<SurfaceMaterial>>,
    named: HashMap<String, Handle<SurfaceMaterial>>,
    paints: HashMap<(CarId, PaintId), CarPaint>,
}

impl MaterialLibrary {
    /// Material of a drivable surface in the current environment (the built-in defaults until a
    /// session's environment is built).
    pub fn surface(&self, kind: SurfaceKind) -> Handle<SurfaceMaterial> {
        self.surfaces.get(&kind).cloned().unwrap_or_default()
    }

    /// A named material of the current environment's list (`materials` in its RON file), e.g.
    /// `"wall"`, `"floor"`, `"barrier"`.
    pub fn named(&self, name: &str) -> Option<Handle<SurfaceMaterial>> {
        self.named.get(name).cloned()
    }

    /// The environment the library was last built for (`None` = built-in defaults).
    pub fn environment(&self) -> Option<&str> {
        self.environment.as_deref()
    }

    /// Names of the current environment's materials.
    pub fn names(&self) -> impl Iterator<Item = &str> {
        self.named.keys().map(String::as_str)
    }

    /// The clear-coated `paint` / `paint_accent` materials of `car`'s paint `paint` (shared
    /// handles, created on first use). `None` for an unknown paint.
    pub fn car_paint(
        &mut self,
        materials: &mut Assets<StandardMaterial>,
        car: &CarInfo,
        paint: PaintId,
    ) -> Option<CarPaint> {
        let info = car.paints.iter().find(|p| p.id == paint)?;
        let key = (car.id.clone(), paint);
        let made = self
            .paints
            .entry(key)
            .or_insert_with(|| CarPaint::new(info, materials));
        Some(made.clone())
    }

    /// Builds a material from a definition (textures of its set when shipped, else flat).
    pub fn make(
        &self,
        def: &MaterialDef,
        materials: &mut Assets<SurfaceMaterial>,
    ) -> Handle<SurfaceMaterial> {
        materials.add(self.material(def))
    }

    fn material(&self, def: &MaterialDef) -> SurfaceMaterial {
        let set = def.set.as_deref().and_then(|s| self.textures.get(s));
        let tile = match (def.tile_u > 0.0, set) {
            (true, _) => def.tile_u,
            (false, Some(set)) => set.tile_u,
            (false, None) => 1.0,
        };
        let [r, g, b] = def.color;
        let base = StandardMaterial {
            base_color: Color::srgb(r, g, b),
            base_color_texture: set.map(|s| s.albedo.clone()),
            normal_map_texture: set.map(|s| s.normal.clone()),
            metallic_roughness_texture: set.map(|s| s.rough.clone()),
            perceptual_roughness: def.roughness.clamp(0.02, 1.0),
            metallic: def.metallic.clamp(0.0, 1.0),
            clearcoat: def.clearcoat.clamp(0.0, 1.0),
            clearcoat_perceptual_roughness: def.clearcoat_roughness.clamp(0.02, 1.0),
            uv_transform: Affine2::from_scale(Vec2::splat(1.0 / tile)),
            ..default()
        };
        SurfaceMaterial {
            base,
            extension: SurfaceExtension::new(def.variation, def.hue_variation, def.weather),
        }
    }

    /// Rebuilds the environment part for `environment` (`None` = defaults): the named list
    /// (built-ins overridden by `named`) and every surface (an override by name, else the
    /// built-in default). Returns override names that the named list lacks.
    pub(crate) fn set_environment(
        &mut self,
        environment: Option<&str>,
        named: &HashMap<String, MaterialDef>,
        overrides: &HashMap<SurfaceKind, String>,
        materials: &mut Assets<SurfaceMaterial>,
    ) -> Vec<String> {
        let mut defs: HashMap<String, MaterialDef> = builtin_materials().into_iter().collect();
        defs.extend(named.iter().map(|(n, d)| (n.clone(), d.clone())));
        self.named = defs
            .iter()
            .map(|(name, def)| (name.clone(), self.make(def, materials)))
            .collect();
        self.environment = environment.map(str::to_owned);
        let mut missing = Vec::new();
        self.surfaces = SurfaceKind::ALL
            .into_iter()
            .map(|kind| {
                let handle = match overrides.get(&kind) {
                    Some(name) => self.named.get(name).cloned().unwrap_or_else(|| {
                        missing.push(name.clone());
                        self.make(&default_surface(kind), materials)
                    }),
                    None => self.make(&default_surface(kind), materials),
                };
                (kind, handle)
            })
            .collect();
        missing
    }

    /// Every environment material (for weather updates).
    pub(crate) fn environment_materials(&self) -> impl Iterator<Item = &Handle<SurfaceMaterial>> {
        self.surfaces.values().chain(self.named.values())
    }

    /// Texture images still loading (0 once every shipped set is on the CPU).
    pub fn textures_pending(&self, server: &AssetServer) -> usize {
        self.textures
            .values()
            .flat_map(|s| [&s.albedo, &s.normal, &s.rough])
            .filter(|h| !server.is_loaded_with_dependencies(h.id()))
            .count()
    }
}

/// Replaces a mesh's UVs with world-unit planar coordinates (each vertex projected on the axis
/// plane most perpendicular to its normal) and generates tangents, so library materials tile at
/// their real size on primitives (`Cuboid`, `Plane3d`, …) built at real size.
pub fn with_world_uvs(mut mesh: Mesh) -> Mesh {
    let (
        Some(VertexAttributeValues::Float32x3(positions)),
        Some(VertexAttributeValues::Float32x3(normals)),
    ) = (
        mesh.attribute(Mesh::ATTRIBUTE_POSITION),
        mesh.attribute(Mesh::ATTRIBUTE_NORMAL),
    )
    else {
        return mesh;
    };
    let uvs: Vec<[f32; 2]> = positions
        .iter()
        .zip(normals)
        .map(|(p, n)| {
            let a = Vec3::from_array(*n).abs();
            if a.y >= a.x && a.y >= a.z {
                [p[0], p[2]]
            } else if a.x >= a.z {
                [p[2], -p[1]]
            } else {
                [p[0], -p[1]]
            }
        })
        .collect();
    mesh.insert_attribute(Mesh::ATTRIBUTE_UV_0, uvs);
    if let Err(e) = mesh.generate_tangents() {
        warn_once!("world-UV mesh without tangents: {e}");
    }
    mesh
}

/// Startup: queue every shipped texture set (sets with missing files are skipped, so their
/// materials fall back to flat colours instead of never drawing).
fn load_textures(
    mut commands: Commands,
    server: Res<AssetServer>,
    paths: Option<Res<UserPaths>>,
    mut materials: ResMut<Assets<SurfaceMaterial>>,
) {
    let root = paths
        .map(|p| p.assets_dir.clone())
        .unwrap_or_else(|| "assets".into());
    let mut library = MaterialLibrary::default();
    for &(name, tile_u) in TEXTURE_SETS {
        let file = |map: &str| format!("textures/{name}/{map}.ktx2");
        let maps = ["albedo", "normal", "rough"].map(file);
        if let Some(missing) = maps.iter().find(|m| !Path::new(&root).join(m).is_file()) {
            warn!("textures: {missing} missing; '{name}' materials use flat colours");
            continue;
        }
        let [albedo, normal, rough] = maps;
        library.textures.insert(
            name,
            TextureSet {
                albedo: load_image(&server, albedo, true),
                normal: load_image(&server, normal, false),
                rough: load_image(&server, rough, false),
                tile_u,
            },
        );
    }
    info!("textures: {} sets queued", library.textures.len());
    library.set_environment(None, &HashMap::new(), &HashMap::new(), &mut materials);
    commands.insert_resource(library);
}

// ponytail: textures are uncompressed on the GPU (RGBA8 / RG8, ≈ 250 MB for every set); encode
// BC7/BC5 in tools/textures when a compressor is approved.
/// Loads a tiling texture: repeat addressing, trilinear + anisotropic filtering; normal and
/// roughness maps are linear (`srgb = false`: the KTX2 loader otherwise gamma-decodes RG8).
fn load_image(server: &AssetServer, path: String, srgb: bool) -> Handle<Image> {
    server
        .load_builder()
        .with_settings(move |s: &mut ImageLoaderSettings| {
            s.is_srgb = srgb;
            s.sampler = ImageSampler::Descriptor(ImageSamplerDescriptor {
                address_mode_u: ImageAddressMode::Repeat,
                address_mode_v: ImageAddressMode::Repeat,
                anisotropy_clamp: ANISOTROPY,
                ..ImageSamplerDescriptor::linear()
            });
        })
        .load(path)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_surface_has_a_default_material_from_a_shipped_set() {
        for kind in SurfaceKind::ALL {
            let def = default_surface(kind);
            if let Some(set) = def.set.as_deref() {
                assert!(
                    TEXTURE_SETS.iter().any(|(s, _)| *s == set),
                    "{kind:?} uses unknown set {set}"
                );
            }
            assert!((0.0..=1.0).contains(&def.roughness), "{kind:?}");
        }
    }

    #[test]
    fn texture_sets_have_positive_tiles_and_unique_names() {
        for (i, (name, tile)) in TEXTURE_SETS.iter().enumerate() {
            assert!(*tile > 0.0, "{name}");
            assert!(
                TEXTURE_SETS[..i].iter().all(|(n, _)| n != name),
                "duplicate {name}"
            );
        }
    }

    #[test]
    fn builtin_names_cover_the_roles_track_visuals_need() {
        let names: Vec<String> = builtin_materials().into_iter().map(|(n, _)| n).collect();
        for role in [
            "floor",
            "wall",
            "ceiling",
            "trim",
            "barrier",
            "ribbon_side",
            "metal",
            "plastic_red",
        ] {
            assert!(names.iter().any(|n| n == role), "{role}");
        }
        for (i, n) in names.iter().enumerate() {
            assert!(!names[..i].contains(n), "duplicate {n}");
        }
        for (name, def) in builtin_materials() {
            if let Some(set) = def.set.as_deref() {
                assert!(TEXTURE_SETS.iter().any(|(s, _)| *s == set), "{name}: {set}");
            }
        }
    }

    #[test]
    fn materials_tile_in_world_units() {
        let library = MaterialLibrary::default();
        let def = MaterialDef {
            tile_u: 4.0,
            ..MaterialDef::flat([0.5; 3], 0.5)
        };
        let m = library.material(&def);
        assert!((m.base.uv_transform.matrix2.x_axis.x - 0.25).abs() < 1e-6);
        assert!(m.base.base_color_texture.is_none(), "no set → flat colour");
    }
}
